#!/usr/bin/env python3
"""dev scratch: exhaustive sorting-network enumeration, two independent engines."""
import sys, time
from fractions import Fraction

def build(N):
    NV = 1 << N
    OPS = [(a, b) for a in range(N) for b in range(a + 1, N)]
    HI = {}
    for (a, b) in OPS:
        m = 0
        for v in range(NV):
            if ((v >> a) & 1) and not ((v >> b) & 1):
                m |= 1 << v
        HI[(a, b)] = (m, (1 << b) - (1 << a))
    CUBE = (1 << NV) - 1
    TARGET = 0
    for k in range(N + 1):
        TARGET |= 1 << (NV - (1 << k))
    LO = [0] * NV; HM = [0] * NV
    for v in range(NV):
        k = bin(v).count("1")
        lo = hi = 0
        for c in range(N):
            want = 1 if k >= N - c else 0
            cur = (v >> c) & 1
            if cur and not want: lo |= 1 << c
            elif (not cur) and want: hi |= 1 << c
        LO[v] = lo; HM[v] = hi
    return NV, OPS, HI, CUBE, TARGET, LO, HM

class Ctx:
    def __init__(self, N):
        self.N = N
        (self.NV, self.OPS, self.HI, self.CUBE, self.TARGET,
         self.LO, self.HM) = build(N)

def step(ctx, R, op):
    m, d = ctx.HI[op]
    hit = R & m
    return R if not hit else (R & ~m) | (hit << d)

def lb(ctx, R):
    N = ctx.N
    c = bin(R).count("1"); t = N + 1; h = 0
    while c > t:
        c = (c + 1) // 2; h += 1
    lo = hi = 0; x = R
    while x:
        b = x & -x; i = b.bit_length() - 1
        lo |= ctx.LO[i]; hi |= ctx.HM[i]; x ^= b
    tb = (bin(lo).count("1") + bin(hi).count("1") + 1) // 2
    return h if h > tb else tb

# ---------- engine A: plain DFS over sequences ----------
def dfs_count(ctx, size, noop_prune):
    tot = [0]; tight = [0]; nodes = [0]
    prof = {}
    N = ctx.N
    path_l = list(range(N))  # token positions
    ell = [0] * N
    def rec(R, rem):
        nodes[0] += 1
        if rem == 0:
            if R == ctx.TARGET:
                tot[0] += 1
                K = sum(Fraction(1, 1 << x) for x in ell)
                if K == 1: tight[0] += 1
                k = tuple(sorted(ell)); prof[k] = prof.get(k, 0) + 1
            return
        if lb(ctx, R) > rem: return
        for op in ctx.OPS:
            R2 = step(ctx, R, op)
            if noop_prune and R2 == R: continue
            a, b = op
            moved = [c for c in range(N) if path_l[c] == a or path_l[c] == b]
            for c in moved:
                path_l[c] = a; ell[c] += 1
            rec(R2, rem - 1)
            for c in moved:
                ell[c] -= 1
            # restore positions
            for c in moved:
                pass
            # positions must be restored properly: recompute below
            for c in moved:
                path_l[c] = None
            # fix: caller restores via saved copy
            for c in moved:
                path_l[c] = a
            raise SystemExit("placeholder")
    return None
